begin;
set local lock_timeout = '30s';

-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 13: financial investments, CVM suitability (Res. CVM 30/2021) and investor category terms (D-046). Additive.
-- Public links: the browser never talks to the database. The server hashes the URL token (sha256) and calls
-- service_role-only RPCs that check expiry, single use, a 5-attempt lock and the client's CPF before anything is shown.

-- ---------------------------------------------------------------- financial investments (positions)
create table cw_prod.investment_positions (
  id               uuid primary key default gen_random_uuid(),
  client_id        uuid not null references cw_prod.clients (id) on delete cascade,
  holder_member_id uuid not null,
  account_id       uuid references cw_prod.financial_accounts (id),
  asset_class      text not null check (asset_class in ('FIXED_INCOME', 'TREASURY', 'FUND_FIXED', 'FUND_MULTI', 'FUND_EQUITY', 'STOCKS', 'REITS',
                                                         'DEBENTURES', 'COE', 'CRYPTO', 'FOREIGN', 'OTHER')),
  description      text not null check (length(description) between 1 and 160),
  issuer           text check (length(issuer) <= 120),
  amount           numeric(18,2) not null check (amount >= 0),
  currency         char(3) not null default 'BRL' check (currency in ('BRL', 'USD', 'EUR')),
  country          char(2) not null default 'BR',
  as_of            date check (as_of <= current_date),
  maturity_date    date,
  liquidity        text not null default 'D0' check (liquidity in ('D0', 'D1_D30', 'D31_D180', 'ABOVE_180', 'MATURITY')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  archived_at      timestamptz,
  archived_by      uuid,
  foreign key (holder_member_id, client_id) references cw_prod.family_members (id, client_id)
);
create index on cw_prod.investment_positions (client_id) where archived_at is null;

-- ---------------------------------------------------------------- per-consultant CVM settings (form and term texts)
create table cw_prod.cvm_settings (
  owner_id           uuid primary key references cw_prod.profiles (id) on delete cascade,
  suitability_form   jsonb check (suitability_form is null or (jsonb_typeof(suitability_form) = 'object' and length(suitability_form::text) <= 60000)),
  qualified_term     text check (length(qualified_term) <= 12000),
  professional_term  text check (length(professional_term) <= 12000),
  updated_at         timestamptz not null default now()
);

-- ---------------------------------------------------------------- public links (suitability / investor term)
create table cw_prod.client_links (
  id              uuid primary key default gen_random_uuid(),
  client_id       uuid not null references cw_prod.clients (id) on delete cascade,
  kind            text not null check (kind in ('SUITABILITY', 'INVESTOR_TERM')),
  token_hash      char(64) not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  payload         jsonb not null check (jsonb_typeof(payload) = 'object' and length(payload::text) <= 80000),
  created_by      uuid not null references cw_prod.profiles (id),
  created_at      timestamptz not null default now(),
  expires_at      timestamptz not null,
  used_at         timestamptz,
  revoked_at      timestamptz,
  failed_attempts integer not null default 0
);
create index on cw_prod.client_links (client_id, kind, created_at desc);

create table cw_prod.suitability_assessments (
  id            uuid primary key default gen_random_uuid(),
  client_id     uuid not null references cw_prod.clients (id) on delete cascade,
  link_id       uuid references cw_prod.client_links (id),
  form          jsonb not null,        -- snapshot of the questions answered
  answers       jsonb not null,
  score_pct     integer not null check (score_pct between 0 and 100),
  profile       text not null check (profile in ('CONSERVADOR', 'MODERADO', 'ARROJADO')),
  caps          jsonb not null default '[]',
  confirmed_at  timestamptz not null default now(),
  valid_until   date not null,
  consultant_id uuid references cw_prod.profiles (id)
);
create index on cw_prod.suitability_assessments (client_id, confirmed_at desc);

create table cw_prod.investor_declarations (
  id              uuid primary key default gen_random_uuid(),
  client_id       uuid not null references cw_prod.clients (id) on delete cascade,
  link_id         uuid references cw_prod.client_links (id),
  category        text not null check (category in ('QUALIFIED', 'PROFESSIONAL')),
  financial_total numeric(18,2) not null,
  term_text       text not null,
  full_name       text not null,
  confirmed_at    timestamptz not null default now(),
  consultant_id   uuid references cw_prod.profiles (id)
);
create index on cw_prod.investor_declarations (client_id, confirmed_at desc);

do $$
declare t text;
begin
  foreach t in array array['investment_positions', 'suitability_assessments', 'investor_declarations'] loop
    execute format('alter table cw_prod.%I enable row level security', t);
    execute format('alter table cw_prod.%I force row level security', t);
    execute format('create policy %I on cw_prod.%I for select to authenticated using ((select cw_prod_private.can_access_client(client_id)))', t || '_read', t);
    execute format('revoke all on cw_prod.%I from public, anon, authenticated', t);
    execute format('grant select on cw_prod.%I to authenticated', t);
    execute format('grant all on cw_prod.%I to service_role', t);
    execute format('create trigger t_audit after insert or update or delete on cw_prod.%I for each row execute function cw_prod_private.audit_row()', t);
  end loop;
end $$;

alter table cw_prod.client_links enable row level security;
alter table cw_prod.client_links force row level security;
create policy client_links_read on cw_prod.client_links for select to authenticated
  using ((select cw_prod_private.is_staff()) and (select cw_prod_private.can_access_client(client_id)));
revoke all on cw_prod.client_links from public, anon, authenticated;
grant select (id, client_id, kind, created_by, created_at, expires_at, used_at, revoked_at, failed_attempts) on cw_prod.client_links to authenticated;
grant all on cw_prod.client_links to service_role;
create trigger t_audit after insert or update or delete on cw_prod.client_links for each row execute function cw_prod_private.audit_row();

alter table cw_prod.cvm_settings enable row level security;
alter table cw_prod.cvm_settings force row level security;
create policy cvm_settings_read on cw_prod.cvm_settings for select to authenticated using (owner_id = (select auth.uid()) and (select cw_prod_private.is_staff()));
revoke all on cw_prod.cvm_settings from public, anon, authenticated;
grant select on cw_prod.cvm_settings to authenticated;
grant all on cw_prod.cvm_settings to service_role;
create trigger t_audit after insert or update or delete on cw_prod.cvm_settings for each row execute function cw_prod_private.audit_row();

-- ---------------------------------------------------------------- registry RPCs (investments)
create function cw_prod.registry_upsert_investment(p_client uuid, p_id uuid, p_data jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid := p_id; v_acc uuid := nullif(p_data ->> 'account_id', '')::uuid;
begin
  perform cw_prod_private.require_client(p_client);
  if v_acc is not null and not exists (select 1 from cw_prod.financial_accounts where id = v_acc and client_id = p_client and archived_at is null) then
    perform cw_prod_private.deny();
  end if;
  if v_id is null then
    insert into cw_prod.investment_positions (client_id, holder_member_id, account_id, asset_class, description, issuer, amount, currency, country,
                                            as_of, maturity_date, liquidity)
    values (p_client, (p_data ->> 'holder_member_id')::uuid, v_acc, p_data ->> 'asset_class', btrim(p_data ->> 'description'),
            nullif(btrim(p_data ->> 'issuer'), ''), (p_data ->> 'amount')::numeric, coalesce(nullif(p_data ->> 'currency', ''), 'BRL'),
            coalesce(nullif(p_data ->> 'country', ''), 'BR'), nullif(p_data ->> 'as_of', '')::date, nullif(p_data ->> 'maturity_date', '')::date,
            coalesce(nullif(p_data ->> 'liquidity', ''), 'D0'))
    returning id into v_id;
  else
    update cw_prod.investment_positions set holder_member_id = (p_data ->> 'holder_member_id')::uuid, account_id = v_acc,
      asset_class = p_data ->> 'asset_class', description = btrim(p_data ->> 'description'), issuer = nullif(btrim(p_data ->> 'issuer'), ''),
      amount = (p_data ->> 'amount')::numeric, currency = coalesce(nullif(p_data ->> 'currency', ''), 'BRL'),
      country = coalesce(nullif(p_data ->> 'country', ''), 'BR'), as_of = nullif(p_data ->> 'as_of', '')::date,
      maturity_date = nullif(p_data ->> 'maturity_date', '')::date, liquidity = coalesce(nullif(p_data ->> 'liquidity', ''), 'D0'), updated_at = now()
     where id = v_id and client_id = p_client and archived_at is null;
    if not found then perform cw_prod_private.deny(); end if;
  end if;
  return v_id;
end $$;

create function cw_prod.registry_archive_investment(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid;
begin
  select client_id into v_client from cw_prod.investment_positions where id = p_id and archived_at is null;
  perform cw_prod_private.require_client(v_client);
  update cw_prod.investment_positions set archived_at = now(), archived_by = auth.uid() where id = p_id;
end $$;

-- ---------------------------------------------------------------- staff RPCs (settings and links)
create function cw_prod.cvm_settings_save(p_form jsonb, p_qualified text, p_professional text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  insert into cw_prod.cvm_settings (owner_id, suitability_form, qualified_term, professional_term)
  values (auth.uid(), p_form, nullif(btrim(p_qualified), ''), nullif(btrim(p_professional), ''))
  on conflict (owner_id) do update set suitability_form = excluded.suitability_form, qualified_term = excluded.qualified_term,
    professional_term = excluded.professional_term, updated_at = now();
end $$;

-- New link for a client; any open link of the same kind is revoked (only the newest one works).
create function cw_prod.cvm_link_create(p_client uuid, p_kind text, p_hash text, p_payload jsonb, p_days integer) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_client(p_client);
  if p_days not between 1 and 30 then raise exception 'invalid expiry' using errcode = '22023'; end if;
  if not exists (select 1 from cw_prod.client_personal_data where client_id = p_client and cpf is not null) then
    raise exception 'client cpf required' using errcode = '22023';
  end if;
  update cw_prod.client_links set revoked_at = now() where client_id = p_client and kind = p_kind and used_at is null and revoked_at is null;
  insert into cw_prod.client_links (client_id, kind, token_hash, payload, created_by, expires_at)
  values (p_client, p_kind, p_hash, p_payload, auth.uid(), now() + make_interval(days => p_days))
  returning id into v_id;
  return v_id;
end $$;

create function cw_prod.cvm_link_revoke(p_id uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid;
begin
  select client_id into v_client from cw_prod.client_links where id = p_id;
  if not cw_prod_private.is_staff() then perform cw_prod_private.deny(); end if;
  perform cw_prod_private.require_client(v_client);
  update cw_prod.client_links set revoked_at = now() where id = p_id and used_at is null and revoked_at is null;
end $$;

-- ---------------------------------------------------------------- public RPCs (service_role only)
-- Opens a link: null when missing, expired, used, revoked or locked; wrong CPF counts an attempt (lock at 5).
create function cw_prod.cvm_link_open(p_hash text, p_cpf text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare l cw_prod.client_links; v_cpf text; v_name text;
begin
  select * into l from cw_prod.client_links where token_hash = p_hash for update;
  if not found or l.used_at is not null or l.revoked_at is not null or l.expires_at < now() or l.failed_attempts >= 5 then return null; end if;
  select cpf, full_name into v_cpf, v_name from cw_prod.client_personal_data where client_id = l.client_id;
  if v_cpf is null or v_cpf <> coalesce(p_cpf, '') then
    update cw_prod.client_links set failed_attempts = failed_attempts + 1 where id = l.id;
    return jsonb_build_object('error', 'CPF', 'remaining', greatest(0, 4 - l.failed_attempts));
  end if;
  return jsonb_build_object('kind', l.kind, 'payload', l.payload, 'full_name', v_name, 'cpf', v_cpf,
                            'consultant', (select full_name from cw_prod.profiles where id = l.created_by));
end $$;

-- Completes a link (client's confirmation). Re-checks everything; the server computed the result from the stored payload.
create function cw_prod.cvm_link_complete(p_hash text, p_cpf text, p_result jsonb) returns boolean
language plpgsql security definer set search_path = '' as $$
declare l cw_prod.client_links; v_cpf text; v_name text;
begin
  select * into l from cw_prod.client_links where token_hash = p_hash for update;
  if not found or l.used_at is not null or l.revoked_at is not null or l.expires_at < now() or l.failed_attempts >= 5 then return false; end if;
  select cpf, full_name into v_cpf, v_name from cw_prod.client_personal_data where client_id = l.client_id;
  if v_cpf is null or v_cpf <> coalesce(p_cpf, '') then
    update cw_prod.client_links set failed_attempts = failed_attempts + 1 where id = l.id;
    return false;
  end if;
  if l.kind = 'SUITABILITY' then
    insert into cw_prod.suitability_assessments (client_id, link_id, form, answers, score_pct, profile, caps, valid_until, consultant_id)
    values (l.client_id, l.id, l.payload -> 'form', p_result -> 'answers', (p_result ->> 'score_pct')::integer, p_result ->> 'profile',
            coalesce(p_result -> 'caps', '[]'::jsonb), (now() at time zone 'America/Sao_Paulo')::date + interval '24 months', l.created_by);
  else
    insert into cw_prod.investor_declarations (client_id, link_id, category, financial_total, term_text, full_name, consultant_id)
    values (l.client_id, l.id, l.payload ->> 'category', (l.payload ->> 'financial_total')::numeric, l.payload ->> 'term_text',
            coalesce(v_name, ''), l.created_by);
  end if;
  update cw_prod.client_links set used_at = now() where id = l.id;
  return true;
end $$;

revoke all on function cw_prod.registry_upsert_investment(uuid, uuid, jsonb), cw_prod.registry_archive_investment(uuid),
  cw_prod.cvm_settings_save(jsonb, text, text), cw_prod.cvm_link_create(uuid, text, text, jsonb, integer), cw_prod.cvm_link_revoke(uuid),
  cw_prod.cvm_link_open(text, text), cw_prod.cvm_link_complete(text, text, jsonb) from public, anon, authenticated;
grant execute on function cw_prod.registry_upsert_investment(uuid, uuid, jsonb), cw_prod.registry_archive_investment(uuid),
  cw_prod.cvm_settings_save(jsonb, text, text), cw_prod.cvm_link_create(uuid, text, text, jsonb, integer), cw_prod.cvm_link_revoke(uuid) to authenticated;
grant execute on function cw_prod.cvm_link_open(text, text), cw_prod.cvm_link_complete(text, text, jsonb) to service_role;

commit;

select 'migração 22 ok' as resultado, count(*) as tabelas_novas_protegidas from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cw_prod' and c.relforcerowsecurity and c.relname in ('investment_positions','cvm_settings','client_links','suitability_assessments','investor_declarations');
